custom_fields.board:
[[[
  const date = new Date();
  const weekday = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  const tomorrow = new Date(date);
  tomorrow.setDate(date.getDate() + 1);
  const dateLabel = date.toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).toUpperCase();
  const eventLines = (entity) => (states[entity]?.state || '').split('\n').filter(Boolean).map((line) => { const [title, when] = line.split('||'); return { title: title || 'Untitled', when: when || 'All day' }; });
  const today = eventLines('input_text.calendar_today_events');
  const tomorrowEvents = eventLines(`input_text.calendar_${weekday[tomorrow.getDay()]}_events`);
  const rows = (events) => events.slice(0, 4).map((event) => `<div class="event"><span class="event-time">${event.when}</span><span>${event.title}</span></div>`).join('') || '<div class="event empty">No events scheduled</div>';
  const weather = states['weather.forecast_housevoice_weather'];
  const condition = ({ sunny: 'Sunny', clear: 'Clear', 'clear-night': 'Clear', partlycloudy: 'Partly Cloudy', cloudy: 'Cloudy', rainy: 'Rainy', pouring: 'Rainy', snowy: 'Snowy', 'snowy-rainy': 'Snow' })[weather?.state] || 'Forecast';
  return `<div class="board">
    <div class="art"></div>
    <main>
      <header><div class="title">HOUSEVOICE</div><div class="subtitle">Family Command Center</div><div class="date"><i></i>${dateLabel}<i></i></div></header>
      <div class="schedule"><section><h2>TODAY</h2><div class="rule"></div>${rows(today)}</section><div class="divider"></div><section><h2>TOMORROW</h2><div class="rule"></div>${rows(tomorrowEvents)}</section></div>
    </main>
    <aside><div class="weather-art"></div><div class="condition">${condition}</div><div class="gold-rule"></div><div class="high-low"><div><b>HIGH</b><strong>--°</strong></div><div><b>LOW</b><strong>--°</strong></div></div></aside>
    <footer><div class="scripture">“Give thanks to the Lord, for he is good.”</div><div class="verse"><i></i>PSALM 107:1<i></i></div></footer>
  </div>`;
]]]
